import Vapor

extension MCPController {
    static let versionField = Schema.integer("Current `version` of the object as last read (optimistic concurrency). A stale value returns `version_conflict`; re-read and retry.", min: 1)

    /// Planning core: projects, tasks, comments, attachments (read), columns. Workflow tools: `MCPWorkflowTools.swift`.
    static let coreTools: [Tool] = [
        Tool(name: "list_projects", scope: "projects:read",
             description: "List the projects this connection may access (id, name, description, colour, parentID). Projects nest freely; parentID is null for roots or when the parent is outside the grant. Call get_project_structure for a project's columns and agent brief.",
             properties: [:], required: []),
        Tool(name: "list_tasks", scope: "tasks:read",
             description: "List all tasks of one project (id, title, description, status, version, columnID). Use get_command_center for a prioritised overview or get_task_context for everything about one task.",
             properties: ["projectID": Schema.uuid("Project to list tasks from.")], required: ["projectID"]),
        Tool(name: "get_task", scope: "tasks:read",
             description: "Read one task (title, description, status open|in_progress|in_review|done, version, columnID). For comments, questions, reviews and progress use get_task_context.",
             properties: ["id": Schema.uuid("Task id.")], required: ["id"]),
        Tool(name: "create_task", scope: "tasks:write",
             description: "Create a task in a project (status open). Use set_task_structure afterwards to mark it a feature or attach it to a parent feature. Requires edit rights on the project.",
             properties: ["projectID": Schema.uuid("Project that will own the task."),
                          "title": Schema.string("Short title, 1 to 200 characters.", maxLength: 200),
                          "description": Schema.string("Optional longer description (Markdown)."),
                          "columnID": Schema.uuid("Optional board column of this project; a done column creates the task as done."),
                          "dueDate": Schema.string("Optional due date: ISO 8601 date-time or a plain date (YYYY-MM-DD, UTC)."),
                          "priority": Schema.integer("Optional priority 0 (none) to 3 (high).", min: 0, max: 3)],
             required: ["projectID", "title"]),
        Tool(name: "update_task", scope: "tasks:write",
             description: "Change title, description, status or project of a task. For normal agent work prefer claim_task, request_review and the question tools, which also move the card to the right board column. Pass the task's current version.",
             properties: ["id": Schema.uuid("Task id."), "version": versionField,
                          "title": Schema.string("New title, 1 to 200 characters.", maxLength: 200),
                          "description": Schema.string("New description (Markdown); replaces the old text."),
                          "status": Schema.string("New status.", values: ["open", "in_progress", "in_review", "done"]),
                          "projectID": Schema.uuid("Move the task to this project (needs edit rights there); it lands without a column.")],
             required: ["id", "version"]),
        Tool(name: "list_comments", scope: "tasks:read",
             description: "List the messages of a task in chronological order (the chat of the card). Each message has authorKind (person|agent), authorName/authorLabel, createdAt and, when it belongs to a card's own chat, questionID or reviewID. Without a filter you get all messages of the task; use questionID or reviewID for one question's or review's chat, thread=task for the task's own chat, authorKind=person with since (ISO 8601) to read only new messages from people. Structured questions use ask_question instead.",
             properties: ["taskID": Schema.uuid("Task id."),
                          "questionID": Schema.uuid("Only the chat of this question (of the same task)."),
                          "reviewID": Schema.uuid("Only the chat of this review (of the same task)."),
                          "thread": Schema.string("task = only messages that belong to no question and no review.", values: ["task"]),
                          "authorKind": Schema.string("Only messages from people or from agents.", values: ["person", "agent"]),
                          "since": Schema.string("ISO 8601 time; only messages created after it.", maxLength: 40)],
             required: ["taskID"]),
        Tool(name: "add_comment", scope: "comments:write",
             description: "Post a message in the chat of a task, or of one of its questions or reviews (pass questionID or reviewID). Markdown, up to 10000 characters. Use it for notes to people and to reply to their messages; use ask_question when you need a decision, and post_progress for status updates.",
             properties: ["taskID": Schema.uuid("Task id."), "body": Schema.string("Message text."),
                          "questionID": Schema.uuid("Post into the chat of this question (it must belong to the task)."),
                          "reviewID": Schema.uuid("Post into the chat of this review (it must belong to the task)."),
                          "agentName": Schema.string("Optional name shown next to your message (for example 'claude-code@build-mac', up to 100 characters).", maxLength: 100),
                          "idempotencyKey": Schema.string("Optional retry key (visible ASCII, up to 200 characters). Re-sending the same key and text returns the original message.", maxLength: 200)],
             required: ["taskID", "body"]),
        Tool(name: "get_progress", scope: "agents:read",
             description: "Read the local-runner agent jobs of a task with run state and the latest checkpoint. Only the project owner may read runner jobs. For the general progress rollup (percent, notes) use get_task_context.",
             properties: ["taskID": Schema.uuid("Task id.")], required: ["taskID"]),
        Tool(name: "list_attachments", scope: "attachments:read",
             description: "List completed attachments of a task (metadata only: id, filename, role, mediaType, size). For build screenshots with build id and platform use list_builds.",
             properties: ["taskID": Schema.uuid("Task id.")], required: ["taskID"]),
        Tool(name: "get_attachment", scope: "attachments:read",
             description: "Read the metadata of one completed attachment. File content is never returned over MCP; humans download it through the app.",
             properties: ["id": Schema.uuid("Attachment id.")], required: ["id"]),
        Tool(name: "list_columns", scope: "projects:read",
             description: "Read the project's kanban board: columns in order with their tasks, plus tasks without a column. A project without own columns returns virtual status columns (mode status). See get_manual section 'Board columns' for the standard agent workflow columns.",
             properties: ["projectID": Schema.uuid("Project id.")], required: ["projectID"]),
        Tool(name: "move_task_to_column", scope: "tasks:write",
             description: "Move a task to a column of its own project at a position (columnID null = no column). Moving into a done column completes the task; moving out of one reopens it.",
             properties: ["id": Schema.uuid("Task id."), "version": versionField,
                          "columnID": Schema.nullable("string", "Target column id of the task's project, or null for 'no column'."),
                          "index": Schema.integer("0-based position in the target column; default end.", min: 0)],
             required: ["id", "version", "columnID"]),
        Tool(name: "create_column", scope: "tasks:write",
             description: "Create a board column in a project (edit rights). To create the whole standard agent workflow use apply_agent_workflow_columns instead.",
             properties: ["projectID": Schema.uuid("Project id."), "name": Schema.string("Column name, 1 to 100 characters.", maxLength: 100),
                          "color": Schema.string("Optional #RRGGBB colour."),
                          "isDone": Schema.boolean("True if moving a task here completes it."),
                          "index": Schema.integer("0-based insert position; default end.", min: 0)],
             required: ["projectID", "name"]),
        Tool(name: "rename_column", scope: "tasks:write",
             description: "Rename a board column. Renaming can change the workflow role the column plays (see get_manual 'Board columns'), so keep the standard names.",
             properties: ["id": Schema.uuid("Column id."), "version": versionField, "name": Schema.string("New name, 1 to 100 characters.", maxLength: 100)],
             required: ["id", "version", "name"]),
        Tool(name: "delete_column", scope: "tasks:write",
             description: "Delete a board column (class C). Its tasks move to moveTo (default: the first remaining column; 'none' = no column). Destructive for the board layout, so it does not run immediately." + confirmationNote,
             properties: ["id": Schema.uuid("Column id."), "version": versionField,
                          "moveTo": Schema.string("Column id that receives the tasks, or the literal 'none' for no column.")],
             required: ["id"]),
    ]
}
